[function] readRealParameter | Package: Modelica.Utilities.Examples | Documentation: Syntax result = readRealParameter(fileName, name); Description This function demonstrates how a function can be implemented that reads the value of a parameter from file. The function performs the following actions: It opens file \"fileName\" and reads the lines of the file. In every line, Modelica line comments (\"// ... end-of-line\ | Parameters: file: from - input String fileName; found: not; found: not; file: on - ;
  protected
    String line;
    String identifier;
    String delimiter;
    Integer nextIndex;
    Integer iline=1;
    Types.TokenValue token;
    String message = | Components: name: String [input]; useDefaultValue: Boolean [input]; then: Boolean [input]; else: Boolean [input]; result: Real [output]; identifier: String; delimiter: String; nextIndex: Integer; iline: Integer; token: Types.TokenValue; message: String; message2: String; found: Boolean; endOfFile: Boolean | Equations: [algorithm]; (line, endOfFile) :=Streams.readLine(fileName, iline); while not found and not endOfFile loop (token, nextIndex) := Strings.scanToken(line); if token.tokenType == Types.TokenType.NoToken then iline := iline + 1; elseif token.tokenType == Types.TokenType.IdentifierToken then if token.string == name then message2 := message + String(iline); (delimiter,nextIndex) := Strings.scanDelimiter(line, nextIndex, {"="}, message2); (result,nextIndex) := Examples.expression(line, nextIndex, message2); (delimiter,nextIndex) := Strings.scanDelimiter(line, nextIndex, {";", ""}, message2); Strings.scanNoToken(line, nextIndex, message2); found := true; else iline := iline + 1; | Dependencies: extends: Modelica.Icons.Function; component_instances: token: Types.TokenValue (from Types); referenced_types: Boolean, Integer, Types.TokenValue, OfFile, String, Real | Extends: Modelica.Icons.Function

